import json
def f(g):
    H=len(g); W=len(g[0])
    pts=[(i,j) for i in range(H) for j in range(W) if g[i][j]==5]
    r0=min(p[0] for p in pts); r1=max(p[0] for p in pts)
    c0=min(p[1] for p in pts); c1=max(p[1] for p in pts)
    def blk_set(rmin,rmax,cmin,cmax): return [(a,b) for a in range(rmin,rmax+1) for b in range(cmin,cmax+1)]
    mid_r=(r0+r1)//2; mid_c=(c0+c1)//2
    TL=blk_set(r0+1,mid_r,c0+1,mid_c); TR=blk_set(r0+1,mid_r,mid_c+1,c1-1)
    BL=blk_set(mid_r+1,r1-1,c0+1,mid_c); BR=blk_set(mid_r+1,r1-1,mid_c+1,c1-1)
    out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v not in (0,5):
                corners={'TL':abs(i-r0)+abs(j-c0),'TR':abs(i-r0)+abs(j-c1),'BL':abs(i-r1)+abs(j-c0),'BR':abs(i-r1)+abs(j-c1)}
                best=min(corners,key=corners.get)
                blks={}
                if best=='TL': blks={v:TL}
                elif best=='TR': blks={v:TR}
                elif best=='BL': blks={v:BL}
                else: blks={v:BR}
                for blk in blks.values():
                    for a,b in blk: out[a][b]=v
    return out
